function vrm(){return svg('54V到GPU核心多相VRM',`${T(35,42,'输入保护、IBC和多相Buck分层','rail')}${T(30,120,'54V+')}${T(30,410,'RTN')}${L(55,115,115,115,'power')}${F(115,115,'F1')}${L(171,115,220,115,'power')}${Z(200,115,405,'TVS54')}${QH(260,115,'Q1','HotSwap')}${QH(330,115,'Q2','ORing')}${L(298,115,292,115,'power')}${L(368,115,430,115,'power')}${C(400,115,405,'Cin')}${B(450,70,155,340,'Q3–Q6 + T1','54V→12V IBC','semi')}${L(430,115,450,115,'power')}${L(55,405,450,405)}${L(605,115,690,115,'power')}${L(605,405,1135,405)}${T(630,94,'12V BUS','rail')}${L(690,115,690,185,'power')}${L(690,115,690,275,'power')}${L(690,115,690,365,'power')}${B(720,145,90,70,'QH1/QL1','Phase 1','semi')}${B(720,235,90,70,'QH2/QL2','Phase 2','semi')}${B(720,325,90,70,'QH3/QL3','Phase 3','semi')}${L(690,185,720,185,'power')}${L(690,275,720,275,'power')}${L(690,365,720,365,'power')}${IND(810,185,'L1')}${IND(810,275,'L2')}${IND(810,365,'L3')}${L(876,185,930,185,'power')}${L(876,275,930,275,'power')}${L(876,365,930,365,'power')}${L(930,185,930,365,'power')}${L(930,275,1010,275,'power')}${C(960,275,405,'Cout')}${B(1010,225,150,100,'GPU/ASIC','Vcore负载')}${B(700,445,220,55,'多相控制器','电流均衡/OVP/Droop')}${P('M810 445V395M810 445V305M810 445V215','control')}`, 'TVS位于54V输入，GPU核心瞬态由多相控制、输出电感和去耦网络处理。')}
